{
  "patches": [
    {
      "oldString": "#rate-dialog { display: flex; flex-direction: column; gap: 32px; padding-top: 16px; }",
      "newString": "#rate-dialog[open] { display: flex; flex-direction: column; gap: 0; padding: 24px; }"
    },
    {
      "oldString": ".rate-trip { font-size: 14px; line-height: 1.5; color: var(--muted); margin-bottom: 16px; }",
      "newString": "#rate-trip { font-size: 14px; line-height: 1.5; color: var(--muted); margin-bottom: 16px; }"
    },
    {
      "oldString": ".rate-option label { flex: 1; min-width: 0; font-size: 16px; line-height: 1.5; font-weight: 500; color: var(--text); }",
      "newString": ".rate-option { font-size: 16px; line-height: 1.5; font-weight: 500; color: var(--text); min-width: 0; }"
    },
    {
      "oldString": ".rate-option input:checked + label { background-color: #fff; box-shadow: inset 2px 0 0 var(--action); }",
      "newString": ".rate-option:has(input:checked) { background-color: var(--surface); box-shadow: inset 0 0 0 2px var(--text); }"
    },
    {
      "oldString": "accent-color: var(--action)",
      "newString": "accent-color: var(--text)"
    },
    {
      "oldString": ".review-total dt, .review-total dd { font-size: 18px; line-height: 1.5; font-weight: 700; color: var(--text); }",
      "newString": "#review-view .review-total dt, #review-view .review-total dd { font-size: 18px; line-height: 1.5; font-weight: 700; color: var(--text); }"
    },
    {
      "oldString": ".review-policy p { font-size: 16px; line-height: 1.5; font-weight: 500; color: var(--text); margin: 0; gap: 8px; }",
      "newString": ".review-policy { display: flex; flex-direction: column; gap: 8px; }\n.review-policy p { font-size: 16px; line-height: 1.5; font-weight: 500; color: var(--text); margin: 0; }"
    }
  ]
}
